package com.makers.loans.controller;
import com.makers.loans.dto.*; import com.makers.loans.service.LoanService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/loans") public class LoanController {private final LoanService service; public LoanController(LoanService service){this.service=service;} @PostMapping public ResponseEntity<LoanResponse> create(Authentication a,@Valid @RequestBody LoanRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(a.getName(),r));} @GetMapping("/mine") public List<LoanResponse> mine(Authentication a){return service.findMine(a.getName());}}
